          (mkC StD (mkS [] [] 0 0 []) S0 (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S0;S1;S1])) 6 8.
Definition ch_iarm0_1_1RB1LB_1LC1RC_1RA0LD_0RC1LD : list rstep := [RB (SWin 3);RB (SCycR 3);RB (SWin 2);RB (SCycL 3 0);RB (SWin 3)].
