  | 2, 1 => iarm2_1_1RB1LB_1LC1RD_0RD1LC_1RA0LC
  | _, _ => iarm0_0_1RB1LB_1LC1RD_0RD1LC_1RA0LC   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

