Proof. vm_compute. reflexivity. Qed.

Definition iarm_1RB1LC_0LA1RB_1LD0RB_1LA0RB (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB
  | 1, 0 => iarm1_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB
  | 2, 0 => iarm2_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB
  | _, _ => iarm0_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB : LRule :=
  mkLRule (mkC StB (mkS [S1;S0;S0] [S1;S0;S0] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S1;S1] [S1;S1;S1] 1 0 [S1]) S0 (mkS [] [] 0 0 [])) 6 8.
Definition ch_farm1_0_1RB1LC_0LA1RB_1LD0RB_1LA0RB : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWinL 2);RB (SCycR 3);RB (SWin 3)].
