Import LadderCheckLiftTr.
Import ListNotations.

Definition mk_1RB1LC_0LC1RA_0LD0RB_1LA1LA (w : Sym) (d : Dir) (n : St) : option Trans :=
  Some (mkTrans w d n).
Local Notation mk := mk_1RB1LC_0LC1RA_0LD0RB_1LA1LA.

(** 1RB1LC_0LC1RA_0LD0RB_1LA1LA *)
Definition tm_1RB1LC_0LC1RA_0LD0RB_1LA1LA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB
  | StA, S1 => mk S1 DL StC
  | StB, S0 => mk S0 DL StC
  | StB, S1 => mk S1 DR StA
  | StC, S0 => mk S0 DL StD
  | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StA
  | StD, S1 => mk S1 DL StA
  end.
(** the instructions the machine never fires; the whole board runs
    on the machine wrapped at them, where firing one halts *)
Definition pins_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list Instr := [].
Local Notation tm := (tm_wrap_trs tm_1RB1LC_0LC1RA_0LD0RB_1LA1LA pins_1RB1LC_0LC1RA_0LD0RB_1LA1LA).

(** ** The family, as DATA

    The successor is a PARAMETER here, not a law: [fam_succ] reads the fill
    of the phase it is in, the code the digits are written in, and the step
    the counter advances by, all off this record. *)
Definition fam_1RB1LC_0LC1RA_0LD0RB_1LA1LA : Fam := mkFam 4 [[S1;S1;S0];[S0;S1;S0];[S1;S1;S1];[S0;S1;S1]] [] [[]] Binary 1 [mkFill 1 [] 0 [2] 0] StB S0 true [].
Local Notation FAM := fam_1RB1LC_0LC1RA_0LD0RB_1LA1LA.

(** ** The ladder, as DATA

    1 window rule(s).  [check_ladder] validates rule i against rules
    0..i-1 only, and [rule_sound] -- ONE theorem, by induction on ladder
    POSITION -- turns that into soundness for all of them. *)
Definition lad_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list (LRule * list rstep) :=
  [(mkLRule (mkC StB (mkS [] [] 0 0 []) S1 (mkS [S0;S1;S1] [] 0 0 [])) (mkC StB (mkS [S0;S1;S1] [] 0 0 []) S1 (mkS [] [] 0 0 [])) 0 5, [RB (SWin 5)])].
Local Notation lad := lad_1RB1LC_0LC1RA_0LD0RB_1LA1LA.

Definition rules_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list LRule := map fst lad.
Local Notation rules := rules_1RB1LC_0LC1RA_0LD0RB_1LA1LA.

Lemma ladder_ok_1RB1LC_0LC1RA_0LD0RB_1LA1LA : check_ladder tm [] lad = true.
Proof. vm_compute. reflexivity. Qed.

Lemma rules_sound_1RB1LC_0LC1RA_0LD0RB_1LA1LA : Forall (RuleSound tm false false) rules.
Proof. apply rule_sound_nil. exact ladder_ok_1RB1LC_0LC1RA_0LD0RB_1LA1LA. Qed.

(** ** The arms, as DATA

    Each is a rule the kernel re-derives from the machine.  [el]/[er] record
    whether that side's tail is known empty: the fill arm must see the end
    of the counter, the interior arms hold against an arbitrary tail. *)
