Definition ch_arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list rstep := [RB (SWin 3);RB (SWinL 11)].
Lemma ok_arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA :
  check_arm tm true true rules arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA ch_arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA = true.
Proof. vm_compute. reflexivity. Qed.
Lemma sound_arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA : RuleSound tm true true arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA.
Proof. eapply arm_sound; [exact rules_sound_1RB1LC_0LC1RA_0LD0RB_1LA1LA | exact ok_arm165_1RB1LC_0LC1RA_0LD0RB_1LA1LA]. Qed.

