(** ** What this board establishes

    25 of 25 arms of the certificate are re-derived by the kernel and
    sound: each [sound_*] is a theorem that the machine, from that arm's
    left-hand side and against any tail the flags permit, reaches the arm's
    right-hand side in exactly the certificate's step count. *)

(** ** The closure: from the RULES to [NeverQuasiHaltsSt]

    The arms below are the case split of [LadderCheck.digs_decomp], built
    from the FAMILY rather than mined: interior arms for the digits below the
    top, and fill arms.  Every certificate arm above is one of these with its
    run lengths pinned to their lower bounds, which is why 25 of them
    collapse to 7 here.

    Both classes are indexed by [LadderCheck]'s ONE arm scheme -- flat below
    a threshold, residue-and-stride at or above it.  The interior class runs
    at threshold 1 stride 1, the fill class at threshold 1
    stride 1.

    [board_neverqh] consumes them, the boot, and one chain per state per fill
    arm, and returns the machine-level theorem. *)
Definition iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA : LRule :=
  mkLRule (mkC StB (mkS [S1;S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S0;S1;S0] [] 0 0 []) S0 (mkS [] [] 0 0 [])) 0 2.
Definition ch_iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list rstep := [RB (SWin 2)].
Lemma ok_iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA :
  check_arm tm false true rules iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA
            ch_iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA = true.
Proof. vm_compute. reflexivity. Qed.

Definition iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA : LRule :=
  mkLRule (mkC StB (mkS [S0;S1;S1] [S0;S1;S1] 1 0 [S1;S1;S0]) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S0;S1;S0]) S0 (mkS [] [] 0 0 [])) 8 10.
Definition ch_iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWin 2);RB (SCycR 5);RB (SWin 5)].
Lemma ok_iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA :
  check_arm tm false true rules iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA
            ch_iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA = true.
Proof. vm_compute. reflexivity. Qed.

