Definition iarm_1RB1LC_0LC1RA_0LD0RB_1LA1LA (d r : nat) : LRule :=
  match d, r with
  | 0, 0 => iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | 0, 1 => iarm0_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | 1, 0 => iarm1_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | 1, 1 => iarm1_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | 2, 0 => iarm2_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | 2, 1 => iarm2_1_1RB1LC_0LC1RA_0LD0RB_1LA1LA
  | _, _ => iarm0_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA   (* unreachable: only d < b-1 and r < N0 + st *)
  end.

Definition farm1_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA : LRule :=
  mkLRule (mkC StB (mkS [S0;S1;S1] [S0;S1;S1] 1 0 []) S0 (mkS [] [] 0 0 []))
          (mkC StB (mkS [S1;S1;S0] [S1;S1;S0] 1 0 [S1;S1;S1]) S0 (mkS [] [] 0 0 [])) 8 14.
Definition ch_farm1_0_1RB1LC_0LC1RA_0LD0RB_1LA1LA : list rstep := [RB (SWin 3);RB (SCycL 3 0);RB (SWinL 6);RB (SCycR 5);RB (SWin 5)].
